// SOP-00 — Validation des inputs et auth webhook
const body = items[0].json.body || items[0].json;
const headers = items[0].json.headers || {};

// Auth check — secret defini en dur (Community Edition, pas de $vars)
const WEBHOOK_SECRET = 'REPLACE_WITH_YOUR_SECRET';
const secret = headers['x-webhook-secret'];
if (secret !== WEBHOOK_SECRET) {
  throw new Error('Unauthorized: invalid webhook secret');
}

// Validation inputs obligatoires
const required = ['linkedin_post_url', 'offre', 'icp_principal', 'roles_cibles', 'secteurs_cibles', 'signaux_forts', 'ton_message'];
const missing = required.filter(k => !body[k]);
if (missing.length > 0) {
  throw new Error('Missing required fields: ' + missing.join(', '));
}

// Defaults
const config = {
  linkedin_post_url: body.linkedin_post_url,
  offre: body.offre,
  icp_principal: body.icp_principal,
  roles_cibles: body.roles_cibles,
  secteurs_cibles: body.secteurs_cibles,
  tailles_entreprise_cibles: body.tailles_entreprise_cibles || '',
  zones_geographiques: body.zones_geographiques || 'France',
  langues_cibles: body.langues_cibles || 'francais',
  signaux_forts: body.signaux_forts,
  signaux_faibles: body.signaux_faibles || '',
  exclusions: body.exclusions || '',
  ton_message: body.ton_message,
  enable_hunter: body.enable_hunter || false,
  score_contact_threshold: body.score_contact_threshold || 70,
  score_review_threshold: body.score_review_threshold || 45,
  campaign_name: body.campaign_name || 'LinkedIn Post Prospecting',
  run_id: 'run_' + new Date().toISOString().slice(0,10).replace(/-/g,'_') + '_' + Math.random().toString(36).slice(2,6)
};

return [{ json: config }];

// Attendre que le run Apify soit termine
const runData = items[0].json;
const runId = runData.data?.id || runData.id;

if (!runId) {
  throw new Error('Apify run ID not found in response');
}

return [{ json: { run_id_apify: runId, status: 'waiting' } }];

// Parser la reponse Claude SOP-01
const raw = items[0].json.text || items[0].json.response?.text || '';

// Extraire le JSON de la reponse
let jsonStr = raw;
const jsonMatch = raw.match(/\{[\s\S]*\}/);
if (jsonMatch) {
  jsonStr = jsonMatch[0];
}

let normalized;
try {
  normalized = JSON.parse(jsonStr);
} catch (e) {
  throw new Error('SOP-01: Failed to parse Claude response as JSON: ' + e.message);
}

// Validation minimale
if (!normalized.post_metadata && !normalized.comments) {
  throw new Error('SOP-01: Missing post_metadata or comments in normalized output');
}

const config = JSON.parse($('Set: Prepare Claude Input Phase 1').item.json.config);

return [{ json: { normalized, config } }];

// Parser la reponse Claude SOP-02 et fusionner avec les donnees existantes
const raw = items[0].json.text || items[0].json.response?.text || '';
let jsonStr = raw;
const jsonMatch = raw.match(/\{[\s\S]*\}/);
if (jsonMatch) jsonStr = jsonMatch[0];

let intentData;
try {
  intentData = JSON.parse(jsonStr);
} catch (e) {
  throw new Error('SOP-02: Failed to parse Claude response: ' + e.message);
}

// Recuperer les donnees precedentes
const prev = $('Code: Parse SOP-01 Output').item.json;
const normalized = prev.normalized;
const config = prev.config;

// Fusionner intent dans raw_leads
const rawLeads = (normalized.raw_leads || []).map(lead => {
  const intent = (intentData.intent_analysis || []).find(i => i.comment_id === lead.source_comment_id);
  return {
    ...lead,
    intent_level: intent?.intent_level || 'no_intent',
    intent_signals: intent?.intent_signals || [],
    business_relevance: intent?.business_relevance || 'none'
  };
});

return [{ json: {
  post_metadata: normalized.post_metadata,
  raw_leads: rawLeads,
  detected_keywords: intentData.detected_keywords || [],
  intent_analysis: intentData.intent_analysis || [],
  config: config,
  warnings_phase1: normalized.warnings || [],
  warnings_phase2: intentData.warnings || []
}}];

// SOP-03 Phase A — Preparer les URLs de profil pour Unipile batch
const rawLeads = items[0].json.raw_leads || [];

// Filtrer les leads avec URL de profil
const leadsWithUrl = rawLeads.filter(l => l.commenter_profile_url);
const leadsWithoutUrl = rawLeads.filter(l => !l.commenter_profile_url);

// Paginer par lots de 100 (limite Unipile)
const batches = [];
for (let i = 0; i < leadsWithUrl.length; i += 100) {
  batches.push(leadsWithUrl.slice(i, i + 100));
}

const output = batches.map((batch, idx) => ({
  json: {
    batch_index: idx,
    batch_size: batch.length,
    leads: batch,
    profile_urls: batch.map(l => l.commenter_profile_url)
  }
}));

// Ajouter un warning pour les leads sans URL
if (leadsWithoutUrl.length > 0) {
  output[0].json.warnings = [
    leadsWithoutUrl.length + ' leads sans URL de profil — enrichissement par nom requis'
  ];
}

return output;

// SOP-03 Phase B — Fusionner les donnees Unipile avec les leads
const enrichedProfiles = items[0].json.data || items[0].json.profiles || items[0].json || [];
const prevData = $('Code: Merge SOP-01 + SOP-02').item.json;
const rawLeads = prevData.raw_leads || [];

// Mapping seniority
function estimateSeniority(title) {
  if (!title) return 'unknown';
  const t = title.toLowerCase();
  if (/\b(ceo|cto|cmo|coo|cfo|founder|co-founder|president)\b/.test(t)) return 'c_level';
  if (/\b(vp|vice president)\b/.test(t)) return 'vp';
  if (/\b(director|directeur|directrice)\b/.test(t)) return 'director';
  if (/\b(head of|responsable)\b/.test(t)) return 'head';
  if (/\b(manager|chef de projet)\b/.test(t)) return 'manager';
  if (/\b(senior|lead|principal)\b/.test(t)) return 'senior';
  if (/\b(junior|stagiaire|intern|assistant)\b/.test(t)) return 'junior';
  return 'mid';
}

// Completude
function calcCompleteness(profile) {
  const fields = ['first_name','last_name','headline','current_role','current_company','industry','location','company_size'];
  const filled = fields.filter(f => profile[f] && profile[f] !== 'unknown').length;
  return Math.round((filled / fields.length) * 100) / 100;
}

const enrichedLeads = rawLeads.map(lead => {
  // Match par URL profil
  const profile = Array.isArray(enrichedProfiles)
    ? enrichedProfiles.find(p => p.profile_url === lead.commenter_profile_url || p.linkedin_url === lead.commenter_profile_url)
    : null;

  const enriched = {
    lead_id: lead.lead_id,
    source_comment_id: lead.source_comment_id,
    full_name: profile?.full_name || profile?.first_name && profile?.last_name ? (profile.first_name + ' ' + profile.last_name) : lead.commenter_name,
    first_name: profile?.first_name || '',
    last_name: profile?.last_name || '',
    linkedin_profile_url: lead.commenter_profile_url || '',
    headline: profile?.headline || '',
    current_role: profile?.current_position?.title || profile?.headline || '',
    seniority_estimated: estimateSeniority(profile?.current_position?.title || profile?.headline),
    current_company: profile?.current_position?.company_name || profile?.company || '',
    company_domain: profile?.company_domain || '',
    industry: profile?.industry || '',
    location: profile?.location || '',
    company_size: profile?.company_size || '',
    profile_summary: profile?.summary || '',
    enrichment_status: profile ? 'success' : 'not_found',
    comment_text: '',
    intent_level: lead.intent_level || 'no_intent',
    intent_signals: lead.intent_signals || [],
    manual_review_required: !profile
  };

  enriched.data_completeness_ratio = calcCompleteness(enriched);

  // Recuperer le texte du commentaire
  const comment = (prevData.intent_analysis || []).find(c => c.comment_id === lead.source_comment_id);
  enriched.comment_text = comment?.comment_text || '';

  return enriched;
});

return [{ json: {
  post_metadata: prevData.post_metadata,
  enriched_leads: enrichedLeads,
  detected_keywords: prevData.detected_keywords,
  intent_analysis: prevData.intent_analysis,
  config: prevData.config,
  warnings: [
    ...(prevData.warnings_phase1 || []),
    ...(prevData.warnings_phase2 || []),
    ...enrichedLeads.filter(l => l.enrichment_status === 'not_found').map(l => 'Enrichissement echoue pour ' + l.full_name)
  ]
}}];

// Parser la reponse Claude SOP-04+05
const raw = items[0].json.text || items[0].json.response?.text || '';
let jsonStr = raw;
const jsonMatch = raw.match(/\{[\s\S]*\}/);
if (jsonMatch) jsonStr = jsonMatch[0];

let scoringData;
try {
  scoringData = JSON.parse(jsonStr);
} catch (e) {
  throw new Error('SOP-04+05: Failed to parse Claude response: ' + e.message);
}

const prevData = $('Code: SOP-03 Merge Enrichment').item.json;

// Enrichir les qualified_leads avec les donnees de profil completes
const enrichedLeads = prevData.enriched_leads || [];
const qualifiedFull = (scoringData.qualified_leads || []).map(ql => {
  const full = enrichedLeads.find(el => el.lead_id === ql.lead_id);
  return { ...full, ...ql };
});

return [{ json: {
  post_metadata: prevData.post_metadata,
  enriched_leads: prevData.enriched_leads,
  detected_keywords: prevData.detected_keywords,
  scoring: scoringData,
  qualified_leads_full: qualifiedFull,
  review_leads: scoringData.review_leads || [],
  rejected_leads: scoringData.rejected_leads || [],
  config: prevData.config,
  warnings: [...(prevData.warnings || []), ...(scoringData.warnings || [])]
}}];

// Parser messages + preparer le JSON final pre-rapport
const raw = items[0].json.text || items[0].json.response?.text || '';
let jsonStr = raw;
const jsonMatch = raw.match(/\{[\s\S]*\}/);
if (jsonMatch) jsonStr = jsonMatch[0];

let messagesData;
try {
  messagesData = JSON.parse(jsonStr);
} catch (e) {
  throw new Error('SOP-06: Failed to parse Claude response: ' + e.message);
}

const prevData = $('Code: Parse SOP-04+05 Output').item.json;

return [{ json: {
  post_metadata: prevData.post_metadata,
  scoring: prevData.scoring,
  qualified_leads_full: prevData.qualified_leads_full,
  review_leads: prevData.review_leads,
  rejected_leads: prevData.rejected_leads,
  generated_messages: messagesData.generated_messages || [],
  config: prevData.config,
  warnings: [...(prevData.warnings || []), ...(messagesData.warnings || [])]
}}];

// SOP-07 — Preparer les candidats Hunter
const qualifiedLeads = items[0].json.qualified_leads_full || [];
const threshold = items[0].json.config.score_contact_threshold || 70;

const hunterCandidates = qualifiedLeads
  .filter(l => l.final_score >= threshold && l.current_company && l.first_name && l.last_name)
  .map(l => ({
    lead_id: l.lead_id,
    first_name: l.first_name,
    last_name: l.last_name,
    company_domain: l.company_domain || '',
    company_name: l.current_company,
    final_score: l.final_score,
    hunter_priority: l.final_score >= 85 ? 'high' : 'medium'
  }));

return hunterCandidates.map(c => ({ json: c }));

// SOP-07 — Parser les resultats Hunter
const hunterResult = items[0].json.data || items[0].json;

const email = hunterResult?.email || null;
const confidence = hunterResult?.confidence || hunterResult?.score || 0;

return [{ json: {
  lead_id: $('Code: SOP-07 Prepare Hunter Candidates').item.json.lead_id,
  hunter_priority: $('Code: SOP-07 Prepare Hunter Candidates').item.json.hunter_priority,
  email_lookup_status: email ? 'success' : 'not_found',
  email: email,
  email_confidence: confidence,
  email_source_type: hunterResult?.type || 'unknown',
  email_usable: confidence >= 80
}}];

// Assembler le JSON final du pipeline (SOP-08 prep)
const msgData = $('Code: Parse SOP-06 Output').item.json;
const config = msgData.config;

// Collecter les resultats Hunter si disponibles
let hunterResults = [];
try {
  const hunterItems = $('Code: Parse Hunter Results').all();
  hunterResults = hunterItems.map(i => i.json);
} catch (e) {
  // Hunter non active ou pas de resultats
}

const finalJson = {
  pipeline_metadata: {
    campaign_name: config.campaign_name,
    run_id: config.run_id,
    run_date: new Date().toISOString().slice(0, 10),
    source: config.linkedin_post_url,
    pipeline_version: 'V4'
  },
  source_post: msgData.post_metadata,
  summary_stats: {
    ...msgData.scoring.summary_stats,
    messages_generated_count: (msgData.generated_messages || []).length,
    hunter_candidates_count: hunterResults.length,
    hunter_verified_count: hunterResults.filter(h => h.email_usable).length
  },
  qualified_leads: msgData.qualified_leads_full || [],
  review_leads: msgData.review_leads || [],
  rejected_leads: msgData.rejected_leads || [],
  generated_messages: msgData.generated_messages || [],
  optional_email_verification: hunterResults,
  warnings: msgData.warnings || []
};

return [{ json: { final_pipeline_json: finalJson, config: config } }];

// Assembler la reponse finale
const htmlRaw = items[0].json.text || items[0].json.response?.text || '';

// Extraire le HTML
let html = htmlRaw;
const htmlMatch = htmlRaw.match(/<!DOCTYPE html>[\s\S]*<\/html>/i);
if (htmlMatch) html = htmlMatch[0];

const finalJson = $('Code: Assemble Final JSON').item.json.final_pipeline_json;

return [{ json: {
  status: 'success',
  pipeline_json: finalJson,
  report_html: html,
  summary: {
    qualified: finalJson.summary_stats.qualified_count || 0,
    review: finalJson.summary_stats.review_count || 0,
    rejected: finalJson.summary_stats.rejected_count || 0,
    messages: finalJson.summary_stats.messages_generated_count || 0,
    emails_verified: finalJson.summary_stats.hunter_verified_count || 0
  }
}}];

// Branche sans leads qualifies — retourner un rapport vide
const prevData = $('Code: Parse SOP-04+05 Output').item.json;

return [{ json: {
  status: 'no_qualified_leads',
  pipeline_json: {
    pipeline_metadata: { run_id: prevData.config.run_id, run_date: new Date().toISOString().slice(0,10) },
    source_post: prevData.post_metadata,
    summary_stats: prevData.scoring?.summary_stats || {},
    qualified_leads: [],
    review_leads: prevData.review_leads || [],
    rejected_leads: prevData.rejected_leads || [],
    generated_messages: [],
    optional_email_verification: [],
    warnings: [...(prevData.warnings || []), 'Aucun lead qualifie — pipeline arrete avant generation de messages']
  },
  report_html: '<html><body><h1>Aucun lead qualifie</h1><p>Le pipeline n\'a identifie aucun lead correspondant a l\'ICP.</p></body></html>',
  summary: { qualified: 0, review: (prevData.review_leads || []).length, rejected: (prevData.rejected_leads || []).length, messages: 0, emails_verified: 0 }
}}];
